VEGA_CDP_PORT=$(head -1 "$work/profile/DevToolsActivePort") node --input-type=module <<'JS'
import assert from 'node:assert/strict'
import { writeFile } from 'node:fs/promises'
const endpoint = `http://127.0.0.1:${process.env.VEGA_CDP_PORT}`
const tabs = await (await fetch(`${endpoint}/json/list`)).json()
const ws = new WebSocket(tabs.find(t => t.type === 'page').webSocketDebuggerUrl)
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve); ws.addEventListener('error', reject) })
let id = 0
const calls = new Map()
ws.addEventListener('message', ({data}) => {
  const message = JSON.parse(data)
  if (!calls.has(message.id)) return
  const {resolve, reject} = calls.get(message.id)
  calls.delete(message.id)
  if (message.error) reject(new Error(message.error.message))
  else resolve(message.result)
})
function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    calls.set(++id, {resolve, reject})
    ws.send(JSON.stringify({id, method, params}))
  })
}
async function evaluate(expression) {
  const {result, exceptionDetails} = await cdp('Runtime.evaluate', {expression, returnByValue: true})
  if (exceptionDetails) throw new Error(result.description ?? exceptionDetails.text)
  return result.value
}
async function waitFor(expression) {
  for (let i = 0; i < 60; i++) {
    if (await evaluate(expression)) return
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  throw new Error(`Timed out waiting for ${expression}`)
}
const brand = 'document.querySelector(\'button[title="Return to topology"]\')'
const hasText = text => `document.body?.innerText.includes(${JSON.stringify(text)})`
const shortcut = (key, options) => evaluate(`window.dispatchEvent(new KeyboardEvent('keydown', ${JSON.stringify({key, ...options, cancelable: true})}))`)
await cdp('Page.navigate', {url: 'http://127.0.0.1:4179/'})
await waitFor(hasText('Engineering Workstation'))
for (const [width, height] of [[1440, 900], [390, 844]]) {
  await cdp('Emulation.setDeviceMetricsOverride', {width, height, deviceScaleFactor: 1, mobile: false})
  await waitFor(`window.innerWidth === ${width}`)
  const layout = await evaluate(`(() => {
    const button = ${brand};
    const rect = button.getBoundingClientRect();
    const svg = button.querySelector('svg');
    return {
      center: rect.left + rect.width / 2,
      label: button.innerText,
      topButtons: [...button.parentElement.children].filter(el => el.tagName === 'BUTTON').length,
      legacyHeader: Boolean(document.querySelector('#root > div > header')),
