useEffect(() => {
  const el = containerRef.current
  if (!el) return

  let limitX = size.width / 2
  let limitY = size.height / 2
  for (const { x, y } of basePositions.values()) {
    limitX = Math.max(limitX, Math.abs(x) + 64)
    limitY = Math.max(limitY, Math.abs(y) + 64)
  }

  const canPan = () => useVegaStore.getState().stage === 'panopticon'
  const movePan = (dx: number, dy: number) => {
    pan.current.x = Math.max(-limitX, Math.min(limitX, pan.current.x + dx))
    pan.current.y = Math.max(-limitY, Math.min(limitY, pan.current.y + dy))
  }
  movePan(0, 0)

  const onWheel = (event: WheelEvent) => {
    if (!canPan() || event.ctrlKey || event.metaKey) return
    event.preventDefault()
    const scale = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? size.height : 1
    const horizontal = event.shiftKey && event.deltaX === 0
    movePan((horizontal ? event.deltaY : event.deltaX) * scale, horizontal ? 0 : event.deltaY * scale)
  }

  let drag: { id: number; x: number; y: number } | null = null
  const onPointerDown = (event: PointerEvent) => {
    if (!canPan() || !event.isPrimary || event.button !== 0) return
    if (event.target instanceof Element && event.target.closest('button')) return
    el.setPointerCapture(event.pointerId)
    drag = { id: event.pointerId, x: event.clientX, y: event.clientY }
    el.dataset.dragging = 'true'
  }
  const onPointerMove = (event: PointerEvent) => {
    if (!drag || drag.id !== event.pointerId || !canPan()) return
    movePan(drag.x - event.clientX, drag.y - event.clientY)
    drag.x = event.clientX
    drag.y = event.clientY
  }
  const onLostPointerCapture = (event: PointerEvent) => {
    if (drag?.id !== event.pointerId) return
    drag = null
    delete el.dataset.dragging
  }

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.target !== el || !canPan() || event.altKey || event.ctrlKey || event.metaKey) return
    switch (event.key) {
      case 'ArrowLeft': movePan(-48, 0); break
      case 'ArrowRight': movePan(48, 0); break
      case 'ArrowUp': movePan(0, -48); break
      case 'ArrowDown': movePan(0, 48); break
      case 'Home': pan.current = { x: 0, y: 0 }; break
      default: return
    }
    event.preventDefault()
  }

  el.addEventListener('wheel', onWheel, { passive: false })
  el.addEventListener('pointerdown', onPointerDown)
  el.addEventListener('pointermove', onPointerMove)
  el.addEventListener('lostpointercapture', onLostPointerCapture)
  el.addEventListener('keydown', onKeyDown)
  return () => {
    if (drag && el.hasPointerCapture(drag.id)) el.releasePointerCapture(drag.id)
    delete el.dataset.dragging
    el.removeEventListener('wheel', onWheel)
    el.removeEventListener('pointerdown', onPointerDown)
    el.removeEventListener('pointermove', onPointerMove)
    el.removeEventListener('lostpointercapture', onLostPointerCapture)
    el.removeEventListener('keydown', onKeyDown)
  }
}, [basePositions, size])

