      store.setWardenDecision(decision)
      if (decision.execution_status === 'contained_dry_run') {
        store.setThreatMode('CONTAINED')
        store.updateNodeStatus('vm-a', 'isolated')
      } else if (decision.execution_status === 'awaiting_authorization') {
