import assert from 'node:assert/strict'
import { writeFile } from 'node:fs/promises'
const [tab] = await (await fetch(`http://127.0.0.1:${process.env.VEGA_CDP_PORT}/json/list`)).json()
const ws = new WebSocket(tab.webSocketDebuggerUrl)
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve); ws.addEventListener('error', reject) })
let id = 0
const calls = new Map()
ws.addEventListener('message', ({data}) => {
  const m = JSON.parse(data)
  if (!calls.has(m.id)) return
  const [resolve, reject] = calls.get(m.id)
  calls.delete(m.id)
  if (m.error) reject(new Error(m.error.message))
  else resolve(m.result)
})
function cdp(method, params = {}) {
  return new Promise((resolve, reject) => {
    calls.set(++id, [resolve, reject]); ws.send(JSON.stringify({id, method, params}))
  })
}
async function ev(expression) {
  const {result, exceptionDetails} = await cdp('Runtime.evaluate', {expression, returnByValue: true})
  if (exceptionDetails) throw new Error(result.description ?? exceptionDetails.text)
  return result.value
}
async function until(expression) {
  for (let i = 0; i < 80; i++) {
    if (await ev(expression)) return
    await new Promise(resolve => setTimeout(resolve, 50))
  }
  throw new Error(`Timed out waiting for ${expression}`)
}
const brand = `document.querySelector('.vega-brand-halo')`
const graph = `document.querySelector('[aria-label="Topology canvas"]')`
const styles = (property, pseudo = '') => `getComputedStyle(${brand}, '${pseudo}').${property}`
const position = `(() => { const r = ${brand}.getBoundingClientRect(); return [r.x + r.width/2, r.y + r.height/2] })()`
const metrics = (width, height) => cdp('Emulation.setDeviceMetricsOverride', {width, height, deviceScaleFactor: 1, mobile: false})
await metrics(1440, 900)
await cdp('Page.navigate', {url:'http://127.0.0.1:4179/'})
await until(`${graph}?.style.backgroundPosition === '720px 450px' && Boolean(${brand})`)
assert.match(await ev(styles('maskImage', '::before')), /radial-gradient/)
assert.match(await ev(styles('backdropFilter', '::before')), /blur/)
assert.equal(await ev(styles('backgroundColor')), 'rgba(0, 0, 0, 0)')
assert.equal(await ev(styles('borderTopWidth')), '0px')
await cdp('Input.dispatchMouseEvent', {type:'mouseWheel', x: 1220, y: 480, deltaX: 0, deltaY: 400})
await until(`${graph}.style.backgroundPosition === '720px 50px'`)
assert.deepEqual(await ev(position), [720,48])
const {data} = await cdp('Page.captureScreenshot', {format:'png'})
await writeFile('/tmp/vega-halo-dashboard.png', Buffer.from(data,'base64'))
await ev(`${brand}.click()`)
await until(`${graph}.style.backgroundPosition === '720px 450px'`)
await cdp('Emulation.setEmulatedMedia', {features: [{name:'prefers-reduced-transparency', value:'reduce'}]})
await until(`${styles('content', '::before')} === 'none'`)
assert.equal(await ev(styles('backgroundColor')), 'rgb(5, 8, 17)')
await metrics(390, 844)
await until(`${position}[0] === 195`)
console.log('Chrome passed: feathered backdrop, no visible button fill or border, stable while panning, recenter, reduced transparency, mobile centering.')
ws.close()
